package com.zorykai.fishing;
import com.zorykai.fishing.core.*;
import com.google.gson.*;
import java.util.*;
import java.sql.*;
import java.math.*;
import java.time.*;
import net.minecraft.server.network.ServerPlayerEntity;
import static com.zorykai.fishing.GameConfig.*;

public final class GameProgress {
 final FishingMod mod;long lastTick;public GameProgress(FishingMod mod){this.mod=mod;}
 public List<JsonObject> quests(){var out=new ArrayList<JsonObject>();for(String file:List.of("missions/daily","missions/weekly","missions/story"))out.addAll(rows(mod.rules.get(file)));return out;}
 public String cycle(JsonObject q){var date=LocalDate.now(ZoneId.of("America/Sao_Paulo"));return switch(str(q,"period","STORY")){case "DAILY"->date.toString();case "WEEKLY"->date.with(java.time.DayOfWeek.MONDAY).toString();default->"permanent";};}
 public PlayerData.Quest quest(PlayerData data,JsonObject q){String id=str(q,"id","");var state=data.quests.computeIfAbsent(id,k->new PlayerData.Quest());String cycle=cycle(q);if(!cycle.equals(state.cycle)){state.cycle=cycle;state.progress=0;state.claimed=false;}if(str(q,"objective","").equals("LEVEL"))state.progress=mod.rules.level(data.xp);if(str(q,"objective","").equals("COLLECTION"))state.progress=data.dex.values().stream().filter(x->x.caught>0).count();if(str(q,"objective","").equals("REGION"))state.progress=data.counters.getOrDefault("lake:"+str(q,"lake",""),0L);return state;}
 public void event(PlayerData data,String type,String species,String size,int count){event(data,type,species,size,count,"");}
 public void event(PlayerData data,String type,String species,String size,int count,String lake){for(var q:quests()){var state=quest(data,q);if(str(q,"objective","").equals(type)&&(!q.has("lake")||str(q,"lake","").equals(lake))&&(!q.has("species")||str(q,"species","").equals(species.replace("cobblemon:","")))&&(!q.has("size")||str(q,"size","").equalsIgnoreCase(size)))state.progress=Math.min(num(q,"target",1),state.progress+count);}}
 public void claimQuest(ServerPlayerEntity p,String id)throws Exception{var q=quests().stream().filter(x->str(x,"id","").equals(id)).findFirst().orElseThrow();var data=mod.data.profile(p.getUuid());var state=quest(data,q);String key=id+"@"+state.cycle;if(state.progress<num(q,"target",1)||data.counters.containsKey("reward:"+key))throw new IllegalArgumentException("Missão incompleta ou recompensa já recebida");mod.finance.reward(p.getUuid(),key,q.getAsJsonObject("reward"),"quest");}
 public double statistic(PlayerData d,String stat){return switch(stat){case "regions"->d.counters.entrySet().stream().filter(x->x.getKey().startsWith("lake:")&&x.getValue()>0).count();case "quests"->d.completedQuests.size();case "records"->d.counters.getOrDefault("records",0L);case "largest"->d.largest;case "captures"->d.captures;case "sales"->d.sales;case "species"->d.dex.values().stream().filter(x->x.caught>0).count();case "shiny"->d.shinyCaptures;case "level"->mod.rules.level(d.xp);case "tournaments"->d.tournamentWins;default->0;};}
 public void claimAchievement(ServerPlayerEntity p,String id)throws Exception{var row=mod.rules.definition("achievements",id);var d=mod.data.profile(p.getUuid());if(d.achievements.contains(id)||statistic(d,str(row,"stat","captures"))<decimal(row,"target",1))throw new IllegalArgumentException("Conquista indisponível");mod.finance.reward(p.getUuid(),id,row.getAsJsonObject("reward"),"achievement");}
 public void grant(PlayerData d,JsonObject reward){d.xp+=num(reward,"xp",0);if(reward.has("minutes"))mod.sessions.addTime(d,num(reward,"minutes",0)*60L,24);if(reward.has("unlock"))d.unlocks.add(str(reward,"unlock",""));if(reward.has("bait"))d.baits.merge(str(reward,"bait",""),num(reward,"amount",1),Math::addExact);if(reward.has("ball"))d.balls.merge(str(reward,"ball",""),num(reward,"amount",1),Math::addExact);if(reward.has("rod"))d.rods.putIfAbsent(str(reward,"rod",""),new PlayerData.Rod());if(reward.has("upgrade")){String rod=str(reward,"rod",d.selectedRod);d.rods.computeIfAbsent(rod,k->new PlayerData.Rod()).upgrades.merge(str(reward,"upgrade","speed"),num(reward,"upgradeLevel",1),Math::max);}if(reward.has("fragments"))d.counters.merge("fragments",(long)num(reward,"fragments",0),Long::sum);}
 public void prestige(ServerPlayerEntity p)throws Exception{if(!bool(mod.rules.get("prestige"),"enabled",false))throw new IllegalStateException("Prestígio desativado");mod.data.update(p.getUuid(),d->{if(mod.rules.level(d.xp)<num(mod.rules.get("levels"),"maximumLevel",100)||d.prestige>=num(mod.rules.get("prestige"),"maximumPrestige",100))throw new IllegalArgumentException("Requisitos de prestígio não atendidos");d.xp=0;d.prestige++;return null;});mod.audit(p.getUuid(),"PRESTIGE",Map.of());}
 public void capture(Connection c,UUID player,String species,double metres,double relative,BigDecimal value)throws Exception{
  for(var def:rows(mod.rules.get("tournaments/example"))){String id=str(def,"id","");var tournament=mod.data.global("tournament:"+id);if(!str(tournament,"state","").equals("ACTIVE")||System.currentTimeMillis()>=tournament.get("ends").getAsLong()||!tournament.getAsJsonObject("participants").has(player.toString()))continue;
   var participant=tournament.getAsJsonObject("participants").getAsJsonObject(player.toString());double old=decimal(participant,"score",0),score=switch(str(def,"metric","LARGEST")){case "QUANTITY"->old+1;case "VALUE"->old+value.doubleValue();case "VARIETY"->{var seen=participant.has("species")?participant.getAsJsonArray("species"):new JsonArray();if(seen.asList().stream().noneMatch(x->x.getAsString().equals(species)))seen.add(species);participant.add("species",seen);yield seen.size();}default->Math.max(old,metres);};participant.addProperty("score",score);mod.data.global("tournament:"+id,tournament);
  }
 }
 public void checkRecords(ServerPlayerEntity player,String species,double size)throws Exception{
  boolean record=mod.store.transaction(c->{var records=mod.data.global("records");var previous=records.has(species)?records.getAsJsonObject(species):new JsonObject();if(size<=decimal(previous,"metres",0))return false;
   var row=new JsonObject();row.addProperty("player",player.getUuid().toString());row.addProperty("name",player.getGameProfile().getName());row.addProperty("metres",size);row.addProperty("at",System.currentTimeMillis());records.add(species,row);
   var history=mod.data.global("record-history");var list=history.has("values")?history.getAsJsonArray("values"):new JsonArray();var entry=row.deepCopy();entry.addProperty("species",species);list.add(entry);while(list.size()>num(mod.rules.get("records"),"historyLimit",100))list.remove(0);history.add("values",list);mod.data.global("record-history",history);mod.data.global("records",records);var d=mod.data.profile(c,player.getUuid());d.counters.merge("records",1L,Long::sum);mod.data.save(c,player.getUuid(),d);return true;
  });if(record&&bool(mod.rules.get("records"),"announce",true))mod.server.getPlayerManager().broadcast(net.minecraft.text.Text.literal("✦ ZORYKAI · "+player.getGameProfile().getName()+" bateu o recorde de "+species+": "+String.format(Locale.ROOT,"%.2f m",size)),false);
 }

 public void startTournament(String id)throws Exception{var d=mod.rules.definition("tournaments/example",id);var old=mod.data.global("tournament:"+id);if(str(old,"state","").equals("ACTIVE"))throw new IllegalStateException("Torneio já ativo");if(str(old,"state","").equals("FINISHED")&&old.has("ranking")){
   var archive=mod.data.global("tournament-history");archive.add(str(old,"run",UUID.randomUUID().toString()),old);mod.data.global("tournament-history",archive);
  }
  var t=new JsonObject();t.addProperty("definition",id);t.addProperty("minimumPlayers",num(d,"minimumPlayers",1));t.addProperty("run",UUID.randomUUID().toString());t.addProperty("state","ACTIVE");t.addProperty("starts",System.currentTimeMillis());t.addProperty("ends",System.currentTimeMillis()+num(d,"durationSeconds",600)*1000L);t.add("participants",new JsonObject());t.add("rewards",d.getAsJsonArray("rewards").deepCopy());mod.data.global("tournament:"+id,t);mod.server.getPlayerManager().broadcast(net.minecraft.text.Text.literal("✦ ZORYKAI · Torneio iniciado: "+str(d,"name",id)),false);
 }
 public void joinTournament(ServerPlayerEntity p,String id)throws Exception{var t=mod.data.global("tournament:"+id);if(!str(t,"state","").equals("ACTIVE")||System.currentTimeMillis()>=t.get("ends").getAsLong())throw new IllegalStateException("Torneio indisponível");var participants=t.getAsJsonObject("participants");if(!participants.has(p.getUuid().toString())){var row=new JsonObject();row.addProperty("name",p.getGameProfile().getName());row.addProperty("score",0);participants.add(p.getUuid().toString(),row);mod.data.global("tournament:"+id,t);}FishingMod.tell(p,"Inscrição confirmada.");}
 public void endTournament(String id)throws Exception{var t=mod.data.global("tournament:"+id);if(!str(t,"state","").equals("ACTIVE"))return;var list=new ArrayList<>(t.getAsJsonObject("participants").entrySet().stream().filter(e->decimal(e.getValue().getAsJsonObject(),"score",0)>0).toList());list.sort(Comparator.<Map.Entry<String,JsonElement>>comparingDouble(e->decimal(e.getValue().getAsJsonObject(),"score",0)).reversed().thenComparing(Map.Entry::getKey));var ranking=new JsonArray();int place=0;for(var e:list){var row=e.getValue().getAsJsonObject().deepCopy();row.addProperty("player",e.getKey());row.addProperty("place",++place);ranking.add(row);}t.add("ranking",ranking);t.addProperty("state","FINISHED");mod.data.global("tournament:"+id,t);mod.server.getPlayerManager().broadcast(net.minecraft.text.Text.literal("✦ ZORYKAI · Torneio encerrado: "+id+". Consulte suas recompensas."),false);}
 public void claimTournament(ServerPlayerEntity p,String id,String run)throws Exception{var t=mod.data.global("tournament:"+id);if(!str(t,"run","").equals(run)){var archive=mod.data.global("tournament-history");if(!archive.has(run))throw new IllegalArgumentException("Torneio inexistente");t=archive.getAsJsonObject(run);}if(!str(t,"state","").equals("FINISHED"))throw new IllegalArgumentException("Torneio não encerrado");if(t.getAsJsonArray("ranking").size()<num(t,"minimumPlayers",1))throw new IllegalStateException("Participantes insuficientes");var d=mod.data.profile(p.getUuid());String key="tournament:"+run;if(d.counters.containsKey("reward:"+key))throw new IllegalStateException("Prêmio já recebido");for(var row:t.getAsJsonArray("ranking")){var r=row.getAsJsonObject();int rank=num(r,"place",0);if(str(r,"player","").equals(p.getUuid().toString())&&rank>0&&rank<=t.getAsJsonArray("rewards").size()){var reward=new JsonObject();reward.addProperty("money",t.getAsJsonArray("rewards").get(rank-1).getAsBigDecimal());reward.addProperty("winner",rank==1);mod.finance.reward(p.getUuid(),key,reward,"tournament");return;}}throw new IllegalStateException("Sem prêmio nesta classificação");}
 public void eventStart(String id)throws Exception{var def=mod.rules.definition("events/example",id);var state=mod.data.global("events");var entry=new JsonObject();entry.addProperty("ends",System.currentTimeMillis()+num(def,"durationSeconds",900)*1000L);state.add(id,entry);mod.data.global("events",state);}
 public double eventMultiplier(String lake,String property)throws Exception{var state=mod.data.global("events");double multiplier=1;for(var row:rows(mod.rules.get("events/example"))){String id=str(row,"id","");if(!state.has(id)||state.getAsJsonObject(id).get("ends").getAsLong()<=System.currentTimeMillis())continue;var areas=row.getAsJsonArray("lakes");if(areas!=null&&!areas.isEmpty()&&areas.asList().stream().noneMatch(x->x.getAsString().equals(lake)))continue;multiplier*=decimal(row,property,1);}return Math.min(10,multiplier);}
 public double speciesMultiplier(String lake,String species)throws Exception{double multiplier=1;var state=mod.data.global("events");for(var def:rows(mod.rules.get("events/example"))){String id=str(def,"id","");if(!state.has(id)||System.currentTimeMillis()>=state.getAsJsonObject(id).get("ends").getAsLong())continue;var areas=def.getAsJsonArray("lakes");if(areas!=null&&!areas.isEmpty()&&areas.asList().stream().noneMatch(x->x.getAsString().equals(lake)))continue;if(def.has("species")&&def.getAsJsonObject("species").has(species))multiplier*=def.getAsJsonObject("species").get(species).getAsDouble();}return Math.min(100,multiplier);}
 public void tick(){long now=System.currentTimeMillis();if(now-lastTick<1000)return;lastTick=now;try{
  for(var def:rows(mod.rules.get("tournaments/example"))){String id=str(def,"id","");var t=mod.data.global("tournament:"+id);if(str(t,"state","").equals("ACTIVE")){if(now>=t.get("ends").getAsLong())endTournament(id);}else{int interval=num(def,"automaticIntervalSeconds",0);long ended=t.has("ends")?t.get("ends").getAsLong():0;var schedule=mod.data.global("schedule");String key="tournament:"+id;if(!schedule.has(key)){schedule.addProperty(key,now);mod.data.global("schedule",schedule);}else if(interval>0&&now-Math.max(ended,schedule.get(key).getAsLong())>=interval*1000L){startTournament(id);schedule.addProperty(key,now);mod.data.global("schedule",schedule);}}}
  for(var def:rows(mod.rules.get("events/example"))){int interval=num(def,"automaticIntervalSeconds",0);if(interval<=0)continue;String id=str(def,"id","");var schedule=mod.data.global("schedule");String key="event:"+id;if(!schedule.has(key))schedule.addProperty(key,now);else if(now-schedule.get(key).getAsLong()>=interval*1000L){eventStart(id);schedule.addProperty(key,now);}mod.data.global("schedule",schedule);}
 }catch(Exception e){mod.fail(e);}}
}
